    // Bench.
    box(1.45, 0.12, 0.42, mat.wood || mat.hullRed, 0, 0.73, -3.45, boat);
    for (const x of [-0.55, 0.55]) {
      box(0.1, 0.65, 0.3, mat.darkMetal, x, 0.38, -3.45, boat);
