    makeBollard(-0.95, -3.85);
    makeBollard(0.95, -3.85);

    // Small deck light.
    cylinderBetween(
      new THREE.Vector3(-0.65, 0.45, -3.65),
      new THREE.Vector3(-0.65, 0.88, -3.65),
