    // -------------------------------------------------------------------------
    // Harbor buoy
    // -------------------------------------------------------------------------

    function createBuoy(scale = 1) {
      const group = new THREE.Group();

      const body = addMesh(
        new THREE.CylinderGeometry(0.34, 0.42, 0.72, 16),
