    // -------------------------------------------------------------------------
    // Distant navigation markers
    // -------------------------------------------------------------------------

    const distantMarkers = [];

    function makeDistantMarker(x, z, color) {
      const group = new THREE.Group();
      group.position.set(x, 0, z);
