    makeDistantMarker(-7, -7, 0xe34b3f);
    makeDistantMarker(8, 5, 0x36b878);
    makeDistantMarker(-10, 9, 0xe34b3f);

    // -------------------------------------------------------------------------
    // Custom camera controls: orbit, pan, zoom, and touch
    // -------------------------------------------------------------------------

    const desired = {
      theta: 0.72,
      phi: 1.12,
      radius: 13.8,
      target: new THREE.Vector3(0, 0.65, 0)
    };

    const current = {
      theta: desired.theta,
      phi: desired.phi,
      radius: desired.radius,
      target: desired.target.clone()
    };

    const pointers = new Map();
    let previousPinchDistance = 0;
    let panning = false;

    renderer.domElement.addEventListener("contextmenu", (event) => {
      event.preventDefault();
    });

    renderer.domElement.addEventListener("pointerdown", (event) => {
      renderer.domElement.setPointerCapture(event.pointerId);
      pointers.set(event.pointerId, {
        x: event.clientX,
        y: event.clientY
      });

      panning = event.button === 2 || event.shiftKey;

      if (pointers.size === 2) {
        const values = [...pointers.values()];
        previousPinchDistance = Math.hypot(
          values[0].x - values[1].x,
          values[0].y - values[1].y
        );
      }
    });

    renderer.domElement.addEventListener("pointermove", (event) => {
      if (!pointers.has(event.pointerId)) return;

      const previous = pointers.get(event.pointerId);
      const dx = event.clientX - previous.x;
      const dy = event.clientY - previous.y;

      pointers.set(event.pointerId, {
        x: event.clientX,
        y: event.clientY
      });

      if (pointers.size === 2) {
        const values = [...pointers.values()];
        const distance = Math.hypot(
          values[0].x - values[1].x,
          values[0].y - values[1].y
        );

        if (previousPinchDistance > 0) {
          desired.radius = THREE.MathUtils.clamp(
            desired.radius * (previousPinchDistance / distance),
            6,
            26
          );
        }

        previousPinchDistance = distance;
        return;
      }

      if (panning) {
        const right = new THREE.Vector3();
        const up = new THREE.Vector3();

        camera.matrixWorld.extractBasis(right, up, new THREE.Vector3());

        const scale = current.radius * 0.00125;
        desired.target
          .addScaledVector(right, -dx * scale)
          .addScaledVector(up, dy * scale);
      } else {
        desired.theta -= dx * 0.006;
        desired.phi = THREE.MathUtils.clamp(
          desired.phi - dy * 0.005,
          0.25,
          1.48
        );
      }
    });

    function endPointer(event) {
      pointers.delete(event.pointerId);
      panning = false;
      previousPinchDistance = 0;
    }

    renderer.domElement.addEventListener("pointerup", endPointer);
    renderer.domElement.addEventListener("pointercancel", endPointer);

    renderer.domElement.addEventListener(
      "wheel",
      (event) => {
        event.preventDefault();
        desired.radius = THREE.MathUtils.clamp(
          desired.radius * Math.exp(event.deltaY * 0.001),
          6,
          26
        );
      },
      { passive: false }
    );

    function resetCamera() {
      desired.theta = 0.72;
      desired.phi = 1.12;
      desired.radius = 13.8;
      desired.target.set(0, 0.65, 0);
    }

    document.getElementById("resetButton").addEventListener("click", resetCamera);

    // -------------------------------------------------------------------------
    // Crane and tender controls
    // -------------------------------------------------------------------------

    const craneButton = document.getElementById("craneButton");
    const tenderButton = document.getElementById("tenderButton");
    const craneStatus = document.getElementById("craneStatus");
    const tenderStatus = document.getElementById("tenderStatus");

    let craneActive = false;
    let cranePhase = 0;
    let tenderActive = false;
    let tenderPhase = 0;

    craneButton.addEventListener("click", () => {
      craneActive = !craneActive;
      craneButton.classList.toggle("active", craneActive);
      craneStatus.textContent = craneActive ? "Crane: Working" : "Crane: Ready";
    });

    tenderButton.addEventListener("click", () => {
      tenderActive = !tenderActive;
      tenderButton.classList.toggle("active", tenderActive);
      tenderStatus.textContent = tenderActive ? "Buoy: Tending" : "Buoy: Moored";
    });

    // -------------------------------------------------------------------------
    // Projected world labels
    // -------------------------------------------------------------------------

    const labels = [
      {
        element: document.getElementById("craneLabel"),
        position: () => boat.localToWorld(new THREE.Vector3(0.8, 2.55, -3.65))
      },
      {
        element: document.getElementById("deckLabel"),
        position: () => boat.localToWorld(new THREE.Vector3(1.25, 0.8, -1.55))
      },
      {
        element: document.getElementById("buoyLabel"),
        position: () => harborBuoy.getWorldPosition(new THREE.Vector3()).add(
          new THREE.Vector3(0, 0.55, 0)
        )
      }
    ];

    const projected = new THREE.Vector3();

    function updateLabels() {
      const width = window.innerWidth;
      const height = window.innerHeight;

      for (const label of labels) {
        label.position().project(camera);

        const visible =
          label.position().z > -1 &&
          label.position().z < 1 &&
          Math.abs(label.position().x) < 1.15 &&
          Math.abs(label.position().y) < 1.15;

        label.element.style.display = visible ? "block" : "none";

        if (visible) {
          const x = (label.position().x * 0.5 + 0.5) * width;
          const y = (-label.position().y * 0.5 + 0.5) * height;
          label.element.style.left = `${x}px`;
          label.element.style.top = `${y}px`;
        }
      }
    }

    // -------------------------------------------------------------------------
    // Animation
    // -------------------------------------------------------------------------

    const clock = new THREE.Clock();
    const hookWorldPosition = new THREE.Vector3();
    const liftedBuoyPosition = new THREE.Vector3();

    function animate() {
      const dt = Math.min(clock.getDelta(), 0.05);
      const elapsed = clock.elapsedTime;

      // Gentle vessel motion.
      boat.rotation.z = THREE.MathUtils.lerp(
        boat.rotation.z,
        Math.sin(elapsed * 0.58) * 0.012,
        1 - Math.exp(-dt * 1.8)
      );

      boat.rotation.x = THREE.MathUtils.lerp(
        boat.rotation.x,
        Math.cos(elapsed * 0.43) * 0.007,
        1 - Math.exp(-dt * 1.6)
      );

      boat.position.y = THREE.MathUtils.lerp(
        boat.position.y,
        0.1 + Math.sin(elapsed * 0.72) * 0.025,
        1 - Math.exp(-dt * 2)
      );

      // Crane cycle.
      if (craneActive) {
        cranePhase += dt * 0.42;

        if (cranePhase > Math.PI * 1.25) {
          cranePhase = cranePhase % (Math.PI * 1.25);
        }

        const cycle = cranePhase < Math.PI * 0.62 ? -0.12 : 0.2;
        const target = THREE.MathUtils.lerp(
          cranePivotTarget,
          cycle,
          1 - Math.exp(-dt * 3)
        );

        boomPivot.rotation.x = target;
      }

      let cranePivotTarget = boomPivot.rotation.x;
      boomPivot.rotation.x = THREE.MathUtils.lerp(
        boomPivot.rotation.x,
        cranePivotTarget,
        1 - Math.exp(-dt * 4)
      );

      trolley.position.z = THREE.MathUtils.lerp(
        trolleyZ,
        2.45 + Math.sin(elapsed * 0.85) * 0.32,
        1 - Math.exp(-dt * 3)
      );

      trolley.position.y = THREE.MathUtils.lerp(
        trolleyY,
        0.48 + Math.sin(elapsed * 1.1) * 0.09,
        1 - Math.exp(-dt * 3)
      );

      // Tend the harbor buoy.
      if (tenderActive) {
        tenderPhase += dt * 0.55;

        if (tenderPhase > 10) {
          tenderPhase = 10;
        }

        const reach = Math.sin(tenderPhase);
        const lift = Math.sin(tenderPhase * 0.73 + 0.8);

        harborBuoy.position.x = 4.25 + reach * 0.65;
        harborBuoy.position.z = -0.7 + reach * 0.35;
        harborBuoy.position.y = Math.sin(elapsed * 1.1) * 0.08 + lift * 0.16;
        harborBuoy.rotation.z = Math.sin(elapsed * 0.8) * 0.08;
        harborBuoy.rotation.x = Math.cos(elapsed * 0.65) * 0.06;
      }

      // Water displacement.
      for (let i = 0; i < waterPosition.count; i++) {
        const x = waterBaseX[i];
        const z = waterBaseZ[i];

        const y =
          Math.sin(x * 0.34 + elapsed * 0.75) * 0.075 +
          Math.cos(z * 0.27 - elapsed * 0.58) * 0.055 +
          Math.sin((x + z) * 0.17 + elapsed * 0.38) * 0.035;

        waterPosition.setY(i, y);
      }

      waterPosition.needsUpdate = true;

      if (Math.floor(elapsed * 4) % 3 === 0) {
        waterGeometry.computeVertexNormals();
      }

      // Wake animation.
      wake.children.forEach((ring, index) => {
        const phase = (elapsed * 0.18 + index * 0.31) % 1;
        ring.scale.setScalar(0.85 + phase * 1.2);
        ring.material.opacity = 0.22 * (1 - phase);
      });

      // Distant buoy motion.
      for (const marker of distantMarkers) {
        marker.group.position.y =
          Math.sin(elapsed * 0.8 + marker.phase) * 0.08;
        marker.group.rotation.z =
          Math.sin(elapsed * 0.65 + marker.phase) * 0.04;
      }

      // Update the lifted buoy's world position from the crane.
      hookGroup.getWorldPosition(hookWorldPosition);
      liftedBuoy.getWorldPosition(liftedBuoyPosition);

      // Smooth camera.
      const smoothing = 1 - Math.exp(-dt * 8);

      current.theta = THREE.MathUtils.lerp(
        current.theta,
        desired.theta,
        smoothing
      );

      current.phi = THREE.MathUtils.lerp(
        current.phi,
        desired.phi,
        smoothing
      );

      current.radius = THREE.MathUtils.lerp(
        current.radius,
        desired.radius,
        smoothing
      );

      current.target.lerp(desired.target, smoothing);

      const sinPhi = Math.sin(current.phi);
      camera.position.set(
        current.target.x + current.radius * sinPhi * Math.sin(current.theta),
        current.target.y + current.radius * Math.cos(current.phi),
        current.target.z + current.radius * sinPhi * Math.cos(current.theta)
      );

      camera.lookAt(current.target);
      boat.updateMatrixWorld(true);

      updateLabels();
      renderer.render(scene, camera);
    }

    window.addEventListener("resize", () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    });

    renderer.setAnimationLoop(animate);

    requestAnimationFrame(() => {
      loading.classList.add("hidden");
      setTimeout(() => loading.remove(), 450);
    });
  </script>
